from functools import cache


class Solution:
    def houseOfCards(self, n: int) -> int:
        @cache
        def go(left, cap):
            if left == 0:
                return 1
            total = 0
            for t in range(1, min(cap, (left + 1) // 3) + 1):
                total += go(left - (3 * t - 1), t - 1)
            return total

        return go(n, n)

