class Solution {
public:
    int houseOfCards(int n) {
        vector<vector<int>> memo(n + 1, vector<int>(n + 1, -1));
        function<int(int, int)> go = [&](int left, int cap) -> int {
            if (left == 0) return 1;
            int& res = memo[left][cap];
            if (res != -1) return res;
            res = 0;
            for (int t = 1; t <= min(cap, (left + 1) / 3); t++)
                res += go(left - (3 * t - 1), t - 1);
            return res;
        };
        return go(n, n);
    }
};

