class Solution {
    private int[][] memo;

    public int houseOfCards(int n) {
        memo = new int[n + 1][n + 1];
        for (int[] row : memo) Arrays.fill(row, -1);
        return go(n, n);
    }

    private int go(int left, int cap) {
        if (left == 0) return 1;
        if (memo[left][cap] != -1) return memo[left][cap];
        int res = 0;
        for (int t = 1; t <= Math.min(cap, (left + 1) / 3); t++)
            res += go(left - (3 * t - 1), t - 1);
        return memo[left][cap] = res;
    }
}

