var houseOfCards = function(n) {
    const memo = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(-1));
    const go = (left, cap) => {
        if (left === 0) return 1;
        if (memo[left][cap] !== -1) return memo[left][cap];
        let res = 0;
        for (let t = 1; t <= Math.min(cap, Math.floor((left + 1) / 3)); t++)
            res += go(left - (3 * t - 1), t - 1);
        return (memo[left][cap] = res);
    };
    return go(n, n);
};

