class Solution:
    def houseOfCards(self, n: int) -> int:
        dp = [0] * (n + 1)
        dp[0] = 1
        w = 2
        while w <= n:
            for j in range(n, w - 1, -1):
                dp[j] += dp[j - w]
            w += 3
        return dp[n]

