class Solution {
public:
    int houseOfCards(int n) {
        vector<long long> dp(n + 1);
        dp[0] = 1;
        for (int w = 2; w <= n; w += 3)
            for (int j = n; j >= w; j--)
                dp[j] += dp[j - w];
        return (int)dp[n];
    }
};

